            at=p; n=number(w,site,signed)
            ck(n>=0 and n<=len(b)-p,f'row {j} {k} invalid count {n} @{at}')
            first=p
            for i in range(n): body(i)
            collections[k]=[at,n,first,p]
        sels[number(1,0xf2ba0e)]+=1
        if mode:
            take(4,0x103fb0e)
