            vec('extra_158',4,0x103fe72,lambda i:take(4,0x103ff79),True)
            def strings(i):
                take(1,0x448f8b1)
                for site in (0x448f8c9,0x448f8e5,0x448f901,0x448f919):
                    n=number(4,0x35b0828)
