            tag=c.num(2,0x155c2f9,True)
            c.cut(4,0x155c31a); c.cut(1,0x155c33d); c.cut(1,0x155c360)
            c.cut(2 if tag>=2 else 1,0x155c38d if tag>=2 else 0x155c3b5)
