def team_tail(c,mode):
    c.cut(1,0x3fc2050)
    c.cut(2,0x11d0f6f)
    if mode:
        for s,t,sgn in [(0x11d10e0,0x11d1344,False),(0x11d139d,0x11d1564,False),(0x11d15c5,0x11d1725,True),(0x11d177b,0x11d18e5,True),(0x11d193b,0x11d1ab7,False)]:
            c.vec(1,s,4,t,sgn)
