DB_KEYS=('table_9.dat','table_extra_9.dat','table_extra_10.dat','table_3.dat','table_5.dat','table_10.dat','table_19.dat','table_25.dat')

def dbroot():
    p=Path(os.environ.get('FM24_DB_DIR') or ROOT/'scratch/data').resolve()
