def archives():
    sys.path.append(str(ROOT.parent/'fm24/tools/python'))
    import zstandard as z
    entries=runpy.run_path(str(ROOT.parent/'fm24/scripts/modding_read_dbdat.py'))['_entries']
    raw={}; meta={}
