            e=es.get(f'{side}_db/{name}'); require((e is not None)==info['present'],name)
            if e is None: continue
            at=34+e['offset']; size=e['packed_size']; end=at+size
            nxt=min((34+x['offset'] for x in es.values() if x['offset']>e['offset']),default=m['toc_offset'])
            require(info['bounds']==[at,end,nxt] and end<=nxt and h(arc[at:end])==info['entry']['sha256'],(side,name,'frame bounds'))
            loc=at; frames=[]; win=[]
