    cs=Cs(CS_ARCH_X86,CS_MODE_64); cs.detail=True; sites={}
    for file in sorted(OUT.glob('instructions.part*.json')):
        for x in j(file):
            f=x['file_offset']; enc=bytes.fromhex(x['bytes']); va=base+pe.get_rva_from_offset(f)
            require(f not in sites and x['VA']==va and enc==raw[f:f+len(enc)],('instruction bytes',f))
