    d=j(OUT/'discovery_t9_wire.json'); require(d['L4']==0 and d['main_binding']=={'client':0,'server':1} and d['sidecar_reader'] is None,'scope')
    for k,v in d['provenance'].items(): require(h((ROOT/k).read_bytes())==v,k)
