            and meta['ordinal_trace_sha256']==h(b''.join(st.pack('<I',v) for v in sorted(ids))),k+' target fingerprints'); ds[k]=ids
    for side,num,w in (('client',5,34),('server',5,48),('client',19,45),('server',19,46),('client',25,127)):
