                    req(not trial['closed'] and (row,kind,at,val)==(fail['row'],fail['kind'],fail['absolute'],fail['value']) and b[at:at+8].hex()==fail['raw'],'first rejected mode'); continue
                req(trial['closed'] and k=='table_9.dat' and mode==m,'unique archive mode')
