    p=PE(EXE); need(digest(p.raw)==EXEH,'editor SHA'); p.pe.parse_data_directories(directories=[3]); m=Cs(CS_ARCH_X86,CS_MODE_64); m.detail=True
    def ins(o): return next(m.disasm(p.raw[o:o+15],p.f2va(o),count=1))
    def blob(o,w): return dict(file_offset=o,VA=p.f2va(o),bytes=p.raw[o:o+w].hex())
    rec={}; extent={}; branches=[]
    def add(o,i=None):
        if o not in rec:
            i=i or ins(o); t=i.operands[0] if i.operands else None
            rec[o]={**blob(o,i.size),'instruction':(i.mnemonic+' '+i.op_str).rstrip()}
            if t and t.type==X86_OP_IMM and (i.mnemonic=='call' or i.mnemonic.startswith('j')):
                rec[o]['direct_target']=p.va2f(t.imm)
        return rec[o]
    for e in CFG_ENTRIES:
        c=ReaderCFG(p,m,e); ii=sorted((p.va2f(v),i) for v,i in c.instructions.items()); prev={a+i.size:(a,i) for a,i in ii}
        extent[e]=dict(end_exclusive=c.function_end_off,reachable=len(ii),external_edges=c.external_edges)
        for a,i in ii:
            s=add(a,i)
            if not i.mnemonic.startswith('j') or i.mnemonic=='jmp': continue
            pred,pi=prev.get(a,(None,None)); typ,_,why=MANUAL_BRANCH.get(a,(None,None,None)); proof=None
            if typ is None and pi and pi.mnemonic=='cmp' and 'ptr [' in pi.op_str and '+ 0x10], 0' in pi.op_str and prev.get(pred,(None,None))[1] is not None:
                ct,ci=prev[pred]
                if ci.mnemonic=='call' and '+ 0x28]' in ci.op_str:
                    typ='IO-result'; why='stream status immediately after read vcall'; f=replays['server']['first_site'].get(ct) or replays['client']['first_site'].get(ct)
                    if f: proof={**f,'control':'truncation before this transfer ends; valid-input exclusion, not execution of editor'}
            if a in (0x105cbb1,0x105e695,0x11d0fa4): proof=neg['wrong_modes']
            if a==0x105d8d8: proof=neg['controls']['NCro_gate_and_one_item']
            if a==0x11d221a: proof=neg['controls']['wrong_raw_ordinal']
            if a==0x11d21c6: proof={'case':'null stream contradicts the earlier live stream transfers and raw identity read'}
            if typ=='dead': proof={'case':'AL=0 on local incoming edge; fallthrough only','xor_site':pred-2}
            if a in (0x105e28d,0x105e312,0x105e392,0x105e2d2,0x105e352,0x105e3d2,0x105e9fe,0x105ea54,0x105ea7d,0x105ead3,0x105eafc,0x105eb52):
                key=why.split()[0]; pr=replays['server']['rows']; proof={str(n):next((dict(row=r['row'],**r['collections'][key]) for r in pr if r['collections'][key]['count']>=n and (n!=0 or r['collections'][key]['count']==0)),None) for n in (0,1,2)}
            branches.append(dict(site=a,function=e,predicate=pred,predicate_instruction=(pi.mnemonic+' '+pi.op_str) if pi else None,
                taken=s.get('direct_target'),fallthrough=a+i.size,classification=typ or 'unresolved',reason=why,first_counterexample=proof))
    anchor=prior['factory']['9']; vf=p.va2f(anchor['vtable_VA']); tbl=0xf49d38; slot=tbl+36
    need(p.va2f(p.f2va(tbl)+struct.unpack_from('<i',p.raw,slot)[0])==0xf48f12,'factory table 9')
    need([p.va2f(struct.unpack_from('<Q',p.raw,vf+q*8)[0]) for q in (2,19,20)]==[0x1065eb0,0x105cb10,0x105fc60],'owner vtable')
    for k in ('factory_rel32','td','col','col_ptr','slot2','slot19'):
        x=anchor[k]; need(blob(x['file_offset'],len(bytes.fromhex(x['bytes'])))==x,'factory bytes '+k)
    add(0xf48b30)
    for a in (0xf48f12,0xf48f17,0xf48f1a,0xf48f1d,0xf48f22,0x1059a4f,0x1059a56,0xf28c13,0xf2ba38,0xf2ba51,0x1065eb0,0x105fc60,
              0x141caa0,0x141cb70,0x105f730,0x141cff0,0x141d110,0x1079c90,0x10788d0,0x15d1540,0x4496fdb,0x4496fb7,0x4496fbb,
              0x3fc2050,0x12e66a0,0xffa602,0x105faa0,0x105f040,0x838890,0x814110,0xdb7f80,0x39dd7d4,0x15bbb00,0xd889e0,
              0x3bf923a,0x3bf9284,0x3bf929a,0x3bf4a90,0x3bf6120,0xf7ef30,0x3d88644,0x1077d65,0x1077d68,0x1077e56,0x41bdbd4): add(a)
