    hashes={k:digest((ROOT/k).read_bytes()) for k in saved}; manifest={x['path']:x['sha256'] for x in J('evidence/MANIFEST.json')['files']}
    for k in (MASTER,IDA,saved[-1]): need(hashes[k]==manifest[k],'manifest '+k)
    need(hashes[MASTER].startswith('7d57477e') and hashes[BASE].startswith('8af89c72'),'baseline')
