        for f,(_,_,_,a,b,_) in fs.items():
            i=ins(a); need(i.mnemonic=='cmp' and i.operands[1].imm==int.from_bytes(f.encode(),'big'),(k,f,'exact 4CC')); add(a); add(b)
    for r in replays.values():
