def fields(k, master, raw, replays, domains):
    idx,w,stride,count_site,_=PARENTS[k]; schema=master['entities']['nation.xml'][0]['fields'][idx]
    need(schema['field']==k,'schema parent '+k)
    counts={}; samples={}
    for side,r in replays.items():
        b=raw[side,'table_9.dat']; placed=[(row['row'],row['collections'][k]) for row in r['rows'] if k in row['collections']]
        ns=[t['count'] for _,t in placed if t['count'] is not None]
        samples[side]=[(j,i,t['start']+i*stride,b[t['start']+i*stride:t['start']+(i+1)*stride])
                       for j,t in placed for i in range(t['count'] or 0)]
        gate=[(j,*t['gate']) for j,t in placed if t['gate'] is not None]
        counts[side]=dict(path_executed=bool(placed),count_sites=len(ns),item_count=len(samples[side]) if ns else None,
            observed_items=len(samples[side]) if placed else None,count_hist=hist(ns),item_bytes_sha256=digest(b''.join(t[3] for t in samples[side])) if ns else None,
            first_count=next((dict(row=j,absolute=t['count_at'],value=t['count'],span=[t['start'],t['end']]) for j,t in placed if t['count'] is not None),None),
            gate_hist=hist(v for _,_,v in gate),first_gate=dict(row=gate[0][0],absolute=gate[0][1],value=gate[0][2]) if gate else None)
    results={}
    for code,(off,fmt,obj,cmp,load,tx) in mappings()[k].items():
        scoped=[f for f in schema['list_item_fields'] if f['field']==code]; need(len(scoped)==1,'scoped occurrence '+code); sch=scoped[0]
        is_enum=sch['type']=='enum'
        enum=master['enums'].get(sch.get('enum_ref',code),{}) if is_enum else {}
        ev={int(x['enum_id'] or x['enum']) for x in enum.get('values',[])}
        sentinels=({-1} if code in REF else {0} if code=='affl' else set())
        def decode(item):
            v=struct.unpack_from('<'+fmt,item,off)[0]
            return (v>>3)&1 if code=='perm' else v&7 if code=='side' else v
        per={}; first_bad=None; any_live=False
        for side,its in samples.items():
            vals=[(r,i,at+off,x[off:off+struct.calcsize('<'+fmt)].hex(),decode(x)) if off is not None else (r,i,None,None,i) for r,i,at,x in its]
            dom=REF.get(code); tk=dom if dom=='person' else f'{side}_{dom}' if dom else None
            target=domains.get(tk) if tk else None
            def ex(v):
                r,i,o,hexval,x=v
                return dict(archive=side,row=r,item=i,absolute=o,hex=hexval,value=x)
            def invalid(v):
                x=v[-1]
                if x in sentinels:return False
                if tk is not None: return target is not None and x not in target
                if is_enum:return not ev or x not in ev
                if sch.get('min_value') is not None:return not int(sch['min_value'])<=x<=int(sch['max_value'])
                return x<0 if sch['type']=='cash' else False
            bad=[ex(v) for v in vals if invalid(v)]; first_bad=first_bad or (bad[0] if bad else None)
            live=[v for v in vals if v[-1] not in sentinels]; any_live|=bool(live)
            per[side]=dict(total=len(vals),sentinel_count=len(vals)-len(live),first_sentinel=next((ex(v) for v in vals if v[-1] in sentinels),None),
                min=min((v[-1] for v in vals),default=None),max=max((v[-1] for v in vals),default=None),
                value_hist=hist(v[-1] for v in vals),first=ex(vals[0]) if vals else None,miss_domain=len(bad),first_miss=bad[0] if bad else None)
            if code in REF:
                hits=[v for v in live if target is not None and v[-1] in target]; hit=hits[0] if hits else None
                per[side]['ordinal_join']=dict(target=tk,performed=target is not None,hit=len(hits),miss=len(bad) if target is not None else None,
                    first_hit={**ex(hit),'target_identity':target[hit[-1]]} if hit else None,first_miss=bad[0] if bad else None)
            if code=='affl':
                club=domains['client_t3']; per[side]['non_reference_control']=dict(target='client_t3',raw_ordinal_hits=sum(v[-1] in club for v in vals),
                    raw_ordinal_misses=sum(v[-1] not in club for v in vals),conclusion='non-discriminating: actual getter boxes byte, zero absent; no Club resolver')
            if code in ('perm','side'): per[side]['raw_byte_hist']=hist(x[off] for _,_,_,x in its)
