            reader_sink=ITEM_TRANSFERS[k][tx][0] if tx is not None else None,enum_source=enum.get('file'),enum_domain=sorted(ev) if ev else None,
            raw_mask={'perm':8,'side':7}.get(code),sentinels=sorted(sentinels),first_counterexample=first_bad,
